import json
from openfeature import api
from openfeature.provider.in_memory_provider import InMemoryFlag, InMemoryProvider

from refund_agent import run_agent          # your agent: run_agent(text, release, call_tool)
from payments import gateway_refund         # your payment gateway client

# Kill switch: the flag is read on every call, so turning it off takes effect at once.
api.set_provider(InMemoryProvider({
    "refund-tool-enabled": InMemoryFlag(default_variant="off",
                                        variants={"on": True, "off": False}),
}))
flags = api.get_client()

def issue_refund(order_id: str, amount: int) -> dict:
    if not flags.get_boolean_value("refund-tool-enabled", False):
        return {"status": "QUEUED_FOR_REVIEW", "order_id": order_id}
    return gateway_refund(order_id, amount, idempotency_key=f"refund-{order_id}")


class RecordedTools:
    """Serve tool responses from a recorded trace, in order. Never call a live API."""

    def __init__(self, recorded_calls):
        self.recorded = list(recorded_calls)
        self.made = []

    def __call__(self, name: str, args: dict) -> dict:
        i = len(self.made)
        self.made.append({"name": name, "args": args})
        if i >= len(self.recorded) or self.recorded[i]["name"] != name:
            raise RuntimeError(f"replay diverged at call {i}: {name}")
        return self.recorded[i]["response"]


def replay(trace: dict, release: dict) -> int:
    tools = RecordedTools(trace["tool_calls"])
    try:
        run_agent(trace["input"], release=release, call_tool=tools)
    except RuntimeError:
        pass                                   # a fixed release may stop earlier or differ
    return sum(1 for c in tools.made if c["name"] == "issue_refund")


with open("traces/tr-4f91.json") as f:
    trace = json.load(f)                       # input, release id, every tool call and response

bad = {"prompt": "refund-agent@v8", "model": "pinned-snapshot", "temperature": 0}
good = {"prompt": "refund-agent@v7", "model": "pinned-snapshot", "temperature": 0}

print("v8 refunds per replay:", [replay(trace, bad) for _ in range(5)])    # expect [2, 2, 2, 2, 2]
print("v7 refunds per replay:", [replay(trace, good) for _ in range(5)])   # expect [1, 1, 1, 1, 1]

# Keep the failure: every future release must pay this ticket exactly once.
with open("evals/refund_cases.jsonl", "a") as f:
    f.write(json.dumps({"trace": "tr-4f91", "expect": {"issue_refund_calls": 1}}) + "\n")
